import {writeFileSync} from 'node:fs';
import {SqliteDataProvider} from '../../dist/index.js';
const [path,barrier,action,phase]=process.argv.slice(2),scope={tenantId:'tenant',applicationId:'app'},provider=new SqliteDataProvider(path),hold=()=>{writeFileSync(barrier,phase);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0);};
const plan=action==='forward'?{fromVersion:0,toVersion:1,transform:value=>({fullName:value.name}),validate:value=>typeof value.fullName==='string'}:{fromVersion:1,targetVersion:0,transform:value=>({name:value.fullName}),validate:value=>typeof value.name==='string'};
try{const preview=provider.rehearseMigration(scope,'people',plan);if(phase==='during'){provider.db.function('test_migration_barrier',()=>{hold();return 0;});provider.db.exec('CREATE TRIGGER test_migration_crash BEFORE INSERT ON business_schema_migration_audit BEGIN SELECT test_migration_barrier(); END');}const config={...plan,digest:preview.digest,outputDigest:preview.outputDigest,evidence:{principalId:'operator',reference:'case',observedAt:123}};if(action==='forward')provider.migrateCollection(scope,'people',config);else provider.rollbackCollection(scope,'people',config);if(phase==='after')hold();throw Error('Expected process termination');}catch(error){process.send?.({error:String(error)});process.exitCode=1;}finally{provider.close();}
